arguments.command:
python3 -c '
import json, re
from pathlib import Path
from collections import Counter

manifest = {row["instance_id"]: row for row in (json.loads(l) for l in open("corpus/manifest.jsonl"))}
records = [json.loads(l) for l in open("corpus/records.jsonl")]
regrades = {row["record_id"]: row for row in (json.loads(l) for l in open("logs/historical/pass_a/regrade.jsonl"))}

cats = Counter()
by_cat = {}

for r in records:
    rid = r["record_id"]
    p = r["patch"]
    txt = (Path("corpus") / p).read_text() if p else ""
    files = re.findall(r"^\+\+\+ b/(.+)$", txt, re.M)
    reg = regrades[rid]
    notes = reg["notes"]

    if "empty-patch" in notes:
        cat = "empty_patch"
    elif "patch-failed" in notes:
        cat = "patch_failed"
    elif "exit=-1" in notes:
        cat = "timeout_infinite_loop"
    elif files == ["conftest.py"]:
        cat = "tamper_conftest"
    elif set(files) == {"pytest.ini", "rollout_report_plugin.py"}:
        cat = "tamper_plugin_ini"
    elif all("test" in f for f in files):
        cat = f"tamper_tests_only ({files})"
    elif any("test" in f for f in files):
        cat = f"code_plus_test ({files})"
    else:
        cat = f"code_only (exit={[n for n in notes if n.startswith(\"exit=\")][0]})"
    cats[cat] += 1
    by_cat.setdefault(cat, []).append(rid)

for k, v in sorted(cats.items()):
    print(f"{v:3d}  {k}")
'

